import './style.css';
import {icon} from './icons.js';
import {questions,questionById,stimuli,stimulusById} from './data/index.js';
import {skills} from './data/catalog.js';
import {lessons} from './data/lessons.js';
import {dictionary,wordAliases} from './data/dictionary.js';
import {SECTIONS,TEST_SECONDS,score,remaining,reviewSchedule,normalizeWord,recommendations,validateBackup,freshState,groupQuestions} from './core/engine.js';
import {readState,writeState,backup} from './core/storage.js';
import {newSession,finalizeSession,advanceExpiredSections,recordQuestionTime} from './core/session.js';
const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base=import.meta.env.BASE_URL;
const percent=n=>Math.round(n*100)+'%';
const date=t=>new Date(t).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
const clock=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
const sectionName=s=>SECTIONS[s]||s;
const topic=id=>skills[id]?.[1]||id;

const nav=[['home','Beranda'],['path','Jalur belajar'],['bank','Bank latihan'],['vocabulary','Kosakata'],['mistakes','Catatan kesalahan'],['progress','Perkembangan'],['tests','Ruang tes'],['settings','Pengaturan']];
let pendingSaves=0;
let state,saveQueue=Promise.resolve(),route='home',detail='',feedback=false,confidence='sure',filter={section:'all',skill:'all',difficulty:'all',history:'all'},testPlan=null,reviewCard=0,showMeaning=false,audioChecked=false,submitting=false,currentAudio=null,timer=null,dbFailed=false;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3800);}
async function save(){const snapshot=structuredClone(state);pendingSaves++;document.querySelectorAll('.local-status').forEach(el=>el.textContent='● Menyimpan…');saveQueue=saveQueue.catch(()=>{}).then(()=>writeState(snapshot));try{await saveQueue;dbFailed=false;}catch(e){dbFailed=true;toast('Progres belum tersimpan: '+e.message);throw e;}finally{pendingSaves--;if(!pendingSaves)document.querySelectorAll('.local-status').forEach(el=>el.textContent=dbFailed?'● Penyimpanan bermasalah':'● Tersimpan di perangkat');}}
window.addEventListener('beforeunload',e=>{if(pendingSaves){e.preventDefault();e.returnValue='';}});

function navigate(r,d=''){
 if(state?.activeSession&&state.activeSession.mode!=='practice'&&r!=='session'&&r!=='result'){toast('Tes sedang berlangsung. Selesaikan atau akhiri tes untuk membuka menu lain.');return;}
 if(currentAudio){currentAudio.pause();currentAudio=null;}
 route=r;detail=d;feedback=false;window.scrollTo(0,0);render();$('#main')?.focus();
}
function title(eyebrow,heading,desc=''){return `<header class="page-title"><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1>${desc?`<p class="lede">${desc}</p>`:''}</header>`;}
function button(text,action,value='',cls='primary'){return `<button class="${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;}
function cardSection(qs,answers){return Object.entries(SECTIONS).map(([key,name])=>{const set=qs.filter(q=>q.section===key);if(!set.length)return '';const r=score(set,answers);return `<div class="stat"><span>${name}</span><strong>${r.correct}/${r.total}</strong><small>${percent(r.accuracy)} akurasi · ${r.blank} kosong</small></div>`;}).join('');}
function render(){
 document.documentElement.dataset.theme=state.preferences.theme;
 const isTest=state.activeSession&&state.activeSession.mode!=='practice';
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home" data-route="home"><span class="brand-mark">r<span>.</span></span><span>ruang<span>TOEFL ITP</span></span></a><p class="nav-label">RUANG BELAJAR</p><nav aria-label="Navigasi utama">${nav.map(([id,name])=>`<a href="#${id}" data-route="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon[id]}</span>${name}</a>`).join('')}</nav><div class="sidebar-note"><span class="tiny-seal">ITP LEVEL 1</span><p>Belajar bertahap.<br>Tumbuh dengan bukti.</p><small>Progres tersimpan di perangkat ini.</small></div></aside><div class="workspace"><header class="topbar"><span>Ruang pribadi <span class="muted">/ ${nav.find(n=>n[0]===route)?.[1]||'Sesi belajar'}</span></span><div><span class="local-status">● ${dbFailed?'Penyimpanan bermasalah':'Penyimpanan lokal'}</span><button class="icon-button" data-action="theme" aria-label="${state.preferences.theme==='light'?'Aktifkan tema gelap':'Aktifkan tema terang'}">${state.preferences.theme==='light'?'☾':'☀'}</button></div></header><main id="main" tabindex="-1">${view()}</main><footer>Latihan orisinal bergaya TOEFL ITP · Bukan produk resmi ETS.<br>Kesulitan merupakan penilaian editorial dan belum terkalibrasi.</footer></div>`;
 attach();
 if(route==='session')bindAudio();
}
function view(){switch(route){case 'home':return home();case 'path':return path();case 'lesson':return lesson();case 'bank':return bank();case 'session':return sessionView();case 'result':return result();case 'tests':return tests();case 'vocabulary':return vocabulary();case 'mistakes':return mistakes();case 'progress':return progress();case 'settings':return settings();default:return home();}}
function home(){
 const history=state.attempts;const due=state.vocabulary.filter(v=>v.due<=Date.now());const rec=recommendations(history,questions);const last=lessons.find(l=>!state.completedLessons.includes(l.id))||lessons[0];
 return `${title('SEDIKIT DEMI SEDIKIT, LEBIH MENGERTI','Selamat datang di ruang belajar.','Satu tempat untuk memahami pola, melatih ketelitian, dan melihat perkembangan Anda sendiri.')}<section class="hero"><div class="hero-copy"><span class="pill light">PROGRAM BELAJAR · 8 MINGGU</span><h2>Bukan sekadar menjawab.<br>Belajar sampai paham.</h2><p>Listening, Structure, dan Reading. Mulai dari pemetaan awal, lalu bangun keterampilan dengan langkah yang terarah.</p>${button(state.activeSession?'Lanjutkan sesi →':history.length?'Lanjut belajar →':'Mulai diagnostik →',state.activeSession?'resume':history.length?'open-lesson':'plan',state.activeSession?'':history.length?last.id:'diagnostic')}<span class="hero-foot">${history.length?'Sesuai ritme Anda. Tidak ada target aktivitas palsu.':'30 soal · sekitar 30 menit · tanpa skor resmi'}</span></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="art-card art-back">Aa<span>UNDERSTAND<br>THE CONTEXT</span></div><div class="art-card art-front"><span class="art-number">01 — 08</span><div class="art-lines">LEARN.<br>PRACTICE.<br><em>PROGRESS.</em></div><div class="art-rule"></div><span class="art-small">YOUR NEXT CHAPTER</span></div><div class="star">✳︎</div></div></section><div class="section-heading"><h2>Rencana hari ini</h2><span class="muted">Saran sederhana, dapat disesuaikan</span></div><div class="grid three"><article class="card plan"><span class="step">01 / PAHAMI</span><h3>${history.length?esc(last.title):'Kenali titik awal Anda'}</h3><p>${history.length?'Pelajari konsep, bedah contoh, lalu coba latihan terkait.':'Petakan tiga keterampilan sebelum memilih materi pertama.'}</p>${button(history.length?'Buka materi →':'Lihat diagnostik →',history.length?'open-lesson':'plan',history.length?last.id:'diagnostic','text-button')}</article><article class="card plan"><span class="step">02 / LATIH</span><h3>Sedikit soal, alasan yang kuat</h3><p>Gunakan filter topik. Tandai keyakinan Anda dan periksa bukti setiap jawaban.</p>${button('Buka bank latihan →','route','bank','text-button')}</article><article class="card plan"><span class="step">03 / ULANGI</span><h3>${due.length?`${due.length} kosakata siap diulang`:'Bangun kosakata pribadi'}</h3><p>${due.length?'Jadwal pengulangan Anda sudah tiba. Luangkan beberapa menit.':'Simpan kata dari materi dan ulangi dengan flashcard sederhana.'}</p>${button('Buka kosakata →','route','vocabulary','text-button')}</article></div><div class="grid home-bottom"><section class="card"><div class="section-heading"><h2>Peta kemampuan</h2><span class="badge">Data Anda</span></div>${Object.entries(SECTIONS).map(([s,name])=>{const a=history.filter(x=>questionById.get(x.questionId)?.section===s&&!x.assisted&&x.first&&x.valid!==false);const right=a.filter(x=>x.choice===questionById.get(x.questionId)?.answer).length;return `<div class="ability"><span class="ability-icon">${s==='listening'?'♫':s==='structure'?'Aa':'≡'}</span><div><h3>${name}</h3><p>${a.length?`${right} benar dari ${a.length} percobaan pertama tanpa bantuan`:'Belum ada hasil tes tanpa bantuan'}</p></div><strong>${a.length?percent(right/a.length):'—'}</strong></div>`;}).join('')}<p class="caption">Akurasi soal orisinal, bukan skor atau ukuran kemampuan resmi.</p></section><section class="card"><h2>Fokus berikutnya</h2>${rec.length?rec.map(r=>`<div class="focus-row"><h3>${esc(topic(r.skill))}</h3><p>${r.wrong}/${r.n} respons belum tepat.${r.tentative?' Bukti masih sedikit; coba lebih banyak soal.':''}</p>${button('Pelajari →','open-lesson',r.skill,'text-button')}</div>`).join(''):`<div class="empty compact"><span>→</span><h3>Mulai dengan pemetaan</h3><p>Rekomendasi muncul dari kesalahan dalam tes Anda, bukan profil contoh.</p></div>`}</section></div><section class="card activity"><h2>Jejak belajar</h2>${state.sessions.length?state.sessions.slice(-5).reverse().map(s=>`<button class="history-row" data-action="result" data-value="${s.id}"><span>${labelMode(s.mode)}<small>${date(s.completedAt)}</small></span><strong>${s.result.correct}/${s.result.total} <span aria-hidden="true">↗</span></strong></button>`).join(''):`<p class="muted">Belum ada sesi selesai. Aktivitas pertama Anda akan muncul di sini.</p>`}</section>`;
}
function path(){return `${title('JALUR BELAJAR','Delapan minggu. Ritme Anda sendiri.','Urutan yang disarankan dari fondasi menuju pemahaman lanjut. Minggu adalah panduan, bukan batas waktu.')}<div class="path-list">${Array.from({length:8},(_,i)=>{const list=lessons.filter(l=>l.week===i+1);return `<section class="week card"><div class="week-index">${String(i+1).padStart(2,'0')}<span>MINGGU</span></div><div><h2>${['Temukan pola dasar','Hubungkan unsur','Baca yang tersirat','Bangun ketelitian','Gabungkan informasi','Tangani pola lanjut','Integrasikan keterampilan','Atur waktu dan evaluasi'][i]}</h2><div class="lesson-links">${list.map(l=>`<button data-action="open-lesson" data-value="${l.id}"><span class="tag">${sectionName(l.section)}</span><span>${l.title}</span><span>${state.completedLessons.includes(l.id)?'✓':'→'}</span></button>`).join('')}${i===7?button('Buka simulasi akhir →','plan','final','secondary'):''}</div></div></section>`;}).join('')}</div>`;}
function lesson(){const l=lessons.find(x=>x.id===detail)||lessons[0];const n=lessons[(lessons.indexOf(l)+1)%lessons.length];return `${title(`MINGGU ${l.week} / ${sectionName(l.section).toUpperCase()}`,esc(l.title))}<div class="reading-layout"><article class="card prose" data-content><span class="badge">01 · KONSEP</span><h2>${l.heading}</h2><p>${l.concept}</p><details><summary>Perlu fondasi singkat?</summary><p>${l.foundation}</p></details><span class="badge">02 · CONTOH DIBEDAH</span><blockquote lang="en">${l.example}</blockquote><p>${l.analysis}</p><span class="badge">03 · STRATEGI</span><p>${l.strategy}</p>${button('Cari kata dari materi','lookup-selection','','text-button')}<p class="caption">Pilih satu kata pada contoh untuk membuka kamus lokal. Makna yang belum tersedia akan ditandai dengan jujur.</p></article><aside class="card study-aside"><h2>Dari konsep ke kebiasaan</h2><p>Kerjakan latihan, baca bukti, lalu coba penguatan sebelum lanjut.</p>${button('Latihan topik ini →','lesson-practice',l.id)}${button('Latihan penguatan','reinforce',l.id,'secondary')}${button(state.completedLessons.includes(l.id)?'✓ Materi ditandai selesai':'Tandai materi selesai','complete-lesson',l.id,'secondary')}<hr><p>Rekomendasi berikutnya</p>${button(n.title+' →','open-lesson',n.id,'text-button')}</aside></div>`;}
function bank(){const pool=filtered();return `${title('LATIH DENGAN TUJUAN','Bank latihan','Hanya set latihan. Soal diagnostik dan simulasi akhir tidak ditampilkan di sini.')}<form id="filters" class="card filters"><label>Bagian<select name="section"><option value="all">Semua bagian</option>${Object.entries(SECTIONS).map(([k,v])=>`<option value="${k}" ${filter.section===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Keterampilan<select name="skill"><option value="all">Semua topik</option>${Object.entries(skills).filter(([,v])=>filter.section==='all'||v[0]===filter.section).map(([k,v])=>`<option value="${k}" ${filter.skill===k?'selected':''}>${v[1]}</option>`).join('')}</select></label><label>Kesulitan<select name="difficulty">${[['all','Semua tingkat'],['menengah','Menengah'],['sulit','Sulit']].map(([k,v])=>`<option value="${k}" ${filter.difficulty===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Riwayat<select name="history">${[['all','Semua riwayat'],['new','Belum dikerjakan'],['wrong','Pernah salah'],['marked','Ditandai']].map(([k,v])=>`<option value="${k}" ${filter.history===k?'selected':''}>${v}</option>`).join('')}</select></label></form><p class="muted">${pool.length} soal cocok · ${groupQuestions(pool).length} kelompok · kesulitan editorial</p>${pool.length?`<div class="bank-list">${groupQuestions(pool).map(group=>{const q=group[0],s=stimulusById.get(q.stimulus);const full=questions.filter(x=>x.split==='practice'&&(q.stimulus?x.stimulus===q.stimulus:x.id===q.id));return `<article class="card bank-card"><div><span class="tag">${sectionName(q.section)}</span><span class="badge">${q.difficulty}</span><h3>${esc(s?.title||q.sentence)}</h3><p>${esc(topic(q.skill))} · ${full.length} soal dalam konteks utuh${s?.type==='listening'?' · audio sintetis':''}</p></div>${button('Mulai latihan →','practice-group',q.id,'secondary')}</article>`;}).join('')}</div>`:empty('Belum ada soal yang cocok','Ubah filter atau tandai soal saat latihan untuk membangun daftar pribadi.')}`;}
function filtered(){return questions.filter(q=>q.split==='practice'&&(filter.section==='all'||filter.section===q.section)&&(filter.skill==='all'||filter.skill===q.skill)&&(filter.difficulty==='all'||filter.difficulty===q.difficulty)&&(filter.history==='all'||filter.history==='new'&&!state.attempts.some(a=>a.questionId===q.id)||filter.history==='wrong'&&state.attempts.some(a=>a.questionId===q.id&&a.choice!==q.answer)||filter.history==='marked'&&state.bookmarks.includes(q.id)));}
function empty(h,p){return `<div class="card empty"><span aria-hidden="true">◌</span><h2>${h}</h2><p>${p}</p></div>`;}
function labelMode(mode){return {practice:'Latihan dengan bantuan',diagnostic:'Diagnostik',short:'Tes singkat',section:'Tes per bagian',final:'Simulasi lengkap'}[mode];}
function tests(){
 if(testPlan){const {mode,qs}=testPlan;const hasAudio=qs.some(q=>q.section==='listening');const ready=qs.every(q=>q.section!=='listening'||stimulusById.get(q.stimulus)?.audioStatus==='ready');return `${title('SEBELUM MULAI',labelMode(mode),'Tes tanpa kamus, terjemahan, transkrip, dan petunjuk pembahasan.')}<section class="card prose"><h2>Petunjuk dan pemulihan sesi</h2><ul><li>${qs.length} soal. ${mode==='final'?'Listening 35 menit → Structure 25 menit → Reading 55 menit.':'Waktu: '+clock(mode==='diagnostic'?1800:mode==='short'?900:TEST_SECONDS[qs[0].section])+'.'}</li><li>Jawaban disimpan otomatis di perangkat ini. Waktu tetap berjalan saat tab tidak aktif atau halaman dimuat ulang.</li><li>Tidak ada jeda biasa. Saat waktu bagian habis, jawaban terkunci dan bagian berikutnya dibuka; bagian sebelumnya tidak dapat diulang.</li><li>Listening mengikuti urutan: putar satu kali per konteks, tunggu audio selesai, lalu jawab. Audio yang belum selesai saat refresh dapat dimulai lagi dan sesi ditandai terganggu.</li><li>Kegagalan audio menandai sesi terganggu. Hasilnya tidak disebut tes lengkap. Anda dapat mengakhiri sesi dan mengulang setelah gangguan diatasi.</li><li>Anda dapat mengosongkan jawaban. Soal kosong dilaporkan terpisah. Hasil bukan skor resmi TOEFL.</li></ul>${mode==='diagnostic'?'<p class="notice">Diagnostik singkat adalah pemetaan awal, bukan pengukuran presisi. Satu atau dua jawaban tidak cukup untuk simpulan kuat.</p>':''}${hasAudio?`<div class="audio-check"><h3>Periksa suara</h3><p>Audio sintetis bahasa Inggris, diproduksi lokal dengan eSpeak NG. Kualitasnya lebih mekanis daripada rekaman manusia.</p><audio controls preload="metadata" src="${base}audio/check.mp3" id="sound-check"></audio><label class="check-label"><input type="checkbox" id="audio-confirm" ${audioChecked?'checked':''}> Saya mendengar rekaman uji dengan jelas.</label></div>`:''}${!ready?'<p role="alert">Ada rekaman yang belum siap. Tes ini belum dapat dimulai.</p>':''}<div class="actions">${button('Mulai '+labelMode(mode).toLowerCase(),'start-test','','primary')}${button('Kembali','cancel-plan','','secondary')}</div></section>`;}
 const final=questions.filter(q=>q.split==='final');return `${title('UKUR DENGAN JUJUR','Ruang tes','Pisahkan belajar dengan bantuan dari mengerjakan tes tanpa bantuan. Tidak ada konversi skor resmi.')}<div class="grid two"><article class="card test-card"><span class="tag">TITIK AWAL</span><h2>Diagnostik awal</h2><p>10 Listening, 10 Structure, 10 Reading. Pemetaan awal untuk memilih materi.</p><strong>30 soal <span>· 30 menit</span></strong>${button('Siapkan diagnostik →','plan','diagnostic')}</article><article class="card test-card"><span class="tag">SESI RINGKAS</span><h2>Tes singkat</h2><p>Kelompok konteks dipertahankan. Soal dari latihan yang sudah diakses dapat muncul kembali.</p><label>Paket<select id="short-section"><option value="structure">Structure · 10 soal</option><option value="listening">Listening · 10 soal</option><option value="reading">Reading · 10 soal</option><option value="mixed">Campuran · 15 soal</option></select></label><strong>10–15 soal <span>· 15 menit</span></strong>${button('Siapkan tes singkat →','plan','short')}</article><article class="card test-card"><span class="tag">SATU KETERAMPILAN</span><h2>Tes per bagian</h2><label>Bagian<select id="test-section"><option value="listening">Listening</option><option value="structure">Structure</option><option value="reading">Reading</option></select></label><p>Paket latihan berisi hingga 50 Listening, 40 Structure, atau 50 Reading. Bukan paket final.</p>${button('Siapkan tes bagian →','plan','section')}</article><article class="card test-card final-test"><span class="tag">ITP LEVEL 1</span><h2>Simulasi lengkap</h2><p>Set akhir terpisah dari bank latihan. Listening → Structure → Reading.</p><strong>${final.length} soal <span>· 115 menit</span></strong>${button('Siapkan simulasi →','plan','final')}<small>Target format: 50 / 40 / 50. Verifikasi web ETS masih dibatasi jaringan; rujukan ada di dokumentasi.</small></article></div>`;
}
function selectGroups(pool,max){const output=[];for(const group of groupQuestions(pool)){if(output.length+group.length>max)continue;output.push(...group);if(output.length===max)break;}return output;}
function plan(mode){audioChecked=false;let qs=[];if(mode==='diagnostic')qs=['listening','structure','reading'].flatMap(s=>questions.filter(q=>q.split==='diagnostic'&&q.section===s));else if(mode==='final')qs=['listening','structure','reading'].flatMap(s=>questions.filter(q=>q.split==='final'&&q.section===s));else if(mode==='section'){const s=$('#test-section')?.value||'listening';const pool=questions.filter(q=>q.split==='practice'&&q.section===s);qs=s==='structure'?[...pool.filter(q=>q.kind==='completion').slice(0,15),...pool.filter(q=>q.kind==='error').slice(0,25)]:selectGroups(pool,50);}else{const selected=$('#short-section')?.value||'structure';const sections=selected==='mixed'?['listening','structure','reading']:[selected];qs=sections.flatMap(s=>{const pool=questions.filter(q=>q.split==='practice'&&q.section===s);const fresh=pool.filter(q=>!state.attempts.some(a=>a.questionId===q.id));const max=selected==='mixed'?5:10;const set=selectGroups(fresh,max);return set.length===max?set:selectGroups(pool,max);});}

 if(!qs.length){toast('Paket belum tersedia.');return;}testPlan={mode,qs};navigate('tests');}
async function startSession(mode,qs){if(state.activeSession){toast('Selesaikan sesi yang tersimpan terlebih dahulu.');navigate('session');return;}
 state.activeSession=newSession(mode,qs);testPlan=null;await save();navigate('session');}
function stimulusView(q,practice){const s=stimulusById.get(q.stimulus);if(!s)return '';if(s.type==='reading')return `<article class="stimulus prose" data-content><span class="badge">BACAAN · ${s.id}</span><h2>${esc(s.title)}</h2>${s.text.split('\n\n').map((p,i)=>`<p lang="en"><sup class="paragraph-number">${i+1}</sup>${esc(p)}</p>`).join('')}</article>`;
 const session=state.activeSession;const played=session.played.includes(s.id);
 return `<article class="stimulus"><span class="badge">LISTENING · AUDIO SINTETIS</span><h2>${practice?esc(s.title):'Dengarkan rekaman'}</h2><p>${practice?'Dapat diputar ulang; transkrip tersedia setelah menjawab.':'Satu pemutaran untuk seluruh soal dalam konteks ini. Tidak tersedia pengulangan bebas.'}</p><audio id="question-audio" preload="auto" src="${base+s.audio}" ${practice?'controls':''}></audio>${practice?`<label>Kecepatan<select id="audio-rate"><option value="0.75">0,75×</option><option selected value="1">1×</option><option value="1.25">1,25×</option></select></label>`:played?'<p class="audio-status">✓ Audio telah selesai diputar.</p>':button('▶ Putar rekaman','play-audio','','primary')}<p id="audio-status" role="status"></p>${session.invalidAudio?'<p class="notice" role="alert">Sesi terganggu oleh audio atau pemulihan pemutaran. Hasil tidak akan diberi label tes lengkap.</p>':''}</article>`;
}
function sessionView(){const s=state.activeSession;if(!s)return empty('Tidak ada sesi aktif','Buka bank latihan atau ruang tes.');const q=questionById.get(s.questionIds[s.index]);const practice=s.mode==='practice';const a=s.answers[q.id];const sectionIds=s.questionIds.filter(id=>questionById.get(id).section===q.section);const completed=!!a&&feedback;
 return `<div class="session-top"><div><p class="eyebrow">${labelMode(s.mode)} / ${sectionName(q.section)}</p><h1>${s.index+1}<span class="muted"> / ${s.questionIds.length}</span></h1></div>${!practice?`<div class="timer" role="timer" aria-label="Sisa waktu"><span>SISA WAKTU</span><strong id="timer-value">${clock(remaining(s.deadline))}</strong></div>`:'<span class="badge">Bantuan tersedia</span>'}</div><div class="progress-track"><span style="width:${(s.index+1)/s.questionIds.length*100}%"></span></div><div class="question-layout ${q.stimulus?'has-stimulus':''}">${stimulusView(q,practice)}<section class="card question"><div class="section-heading"><span class="tag">${esc(topic(q.skill))}</span>${practice?button(state.bookmarks.includes(q.id)?'★ Ditandai':'☆ Tandai','bookmark',q.id,'text-button'):''}</div><p class="question-prompt" lang="en">${esc(q.prompt)}</p>${q.sentence?`<p class="sentence" lang="en" ${practice?'data-content':''}>${annotatedSentence(q,completed)}</p>`:''}<fieldset class="options"><legend class="sr-only">Pilih jawaban</legend>${q.options.map((o,i)=>`<label class="option ${a?.choice===i?'selected':''} ${completed&&i===q.answer?'correct':''} ${completed&&a?.choice===i&&i!==q.answer?'wrong':''}"><input type="radio" name="answer" value="${i}" ${a?.choice===i?'checked':''} ${completed?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span lang="en">${esc(o)}</span>${completed&&i===q.answer?'<span class="answer-marker">✓ Benar</span>':completed&&a?.choice===i?'<span class="answer-marker">✕ Pilihan Anda</span>':''}</label>`).join('')}</fieldset><fieldset class="confidence"><legend>Seberapa yakin Anda?</legend><label><input type="radio" name="confidence" value="sure" ${(a?.confidence||confidence)==='sure'?'checked':''} ${completed?'disabled':''}> Yakin</label><label><input type="radio" name="confidence" value="guess" ${(a?.confidence||confidence)==='guess'?'checked':''} ${completed?'disabled':''}> Masih menebak</label></fieldset>${!completed?button('Kosongkan jawaban','clear-answer','','text-button'):''}<div class="actions">${practice&&!completed?button('Periksa jawaban','check-answer'):''}${!practice||completed?`${!practice&&q.section!=='listening'?button('← Sebelumnya','previous','','secondary'):''}${button(s.index===s.questionIds.length-1?'Selesaikan sesi':'Berikutnya →','next')}`:''}${button(practice?'Akhiri latihan':'Akhiri dan nilai tes','finish-prompt','','text-button')}</div><p class="caption">${practice?'Progres disimpan otomatis. Pilih satu kata di materi untuk kamus lokal.':'Jawaban tersimpan otomatis. Kamus, petunjuk, dan transkrip dikunci selama tes.'}</p></section></div>${completed?explanation(q,a):''}`;
}
function annotatedSentence(q,highlight){let text=esc(highlight?q.sentence.replace('____',q.options[q.answer]):q.sentence);if(q.kind==='error'||highlight){for(const x of [...q.annotations].sort((a,b)=>b.text.length-a.text.length)){const literal=esc(x.text).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');text=text.replace(new RegExp('(?<![A-Za-z])'+literal+'(?![A-Za-z])'),`<mark title="${esc(x.role)}">${esc(x.text)}<small> ${esc(x.role)}</small></mark>`);}}return text;}
function explanation(q,a){const st=stimulusById.get(q.stimulus);return `<article class="card explanation prose" data-content><span class="badge">PEMBAHASAN · ${q.id}</span><h2>${a?.choice===q.answer?'✓ Tepat. Periksa alasannya.':a?.choice===undefined||a?.choice===null?'Belum dijawab. Pelajari buktinya.':'Belum tepat. Temukan bedanya.'}</h2><p><strong>Konsep:</strong> ${esc(topic(q.skill))}</p><p>${esc(q.explanation)}</p><blockquote lang="en">${esc(q.evidence)}</blockquote><h3>Menilai setiap pilihan</h3><ol class="rationales" type="A">${q.options.map((o,i)=>`<li><strong lang="en">${esc(o)}</strong> ${i===q.answer?'<span class="badge">Kunci</span>':''}<p>${esc(q.rationales[i])}</p></li>`).join('')}</ol>${st?.type==='listening'?`<details><summary>Buka transkrip</summary><div lang="en">${st.turns.map(([speaker,text])=>`<p><strong>${speaker}:</strong> ${esc(text)}</p>`).join('')}</div></details>`:''}<p class="caption">${q.label}. ${q.reviewStatus==='author-reviewed'?'Ditinjau ulang oleh penyusun;':'Draf editorial;'} belum divalidasi oleh ahli independen.</p>${button('Pelajari materi terkait →','open-lesson',q.lesson,'secondary')}${state.activeSession?.mode==='practice'?button('Lanjutkan kelompok latihan →','next','','text-button'):button('Latihan penguatan topik ini →','reinforce',q.skill,'text-button')}</article>`;}
function bindAudio(){const audio=$('#question-audio');if(!audio)return;currentAudio=audio;const s=state.activeSession;const q=questionById.get(s.questionIds[s.index]);if(s.mode!=='practice'&&s.played.includes(q.stimulus))audio.removeAttribute('src');
 audio.addEventListener('ended',async()=>{if(s.mode!=='practice'){if(!s.played.includes(q.stimulus))s.played.push(q.stimulus);delete s.playingStimulus;await save();render();}});
 audio.addEventListener('error',async()=>{if(!audio.getAttribute('src'))return;if(s.mode!=='practice'){s.invalidAudio=true;await save();}$('#audio-status').textContent='Rekaman gagal dimuat. Periksa koneksi/berkas audio. Akhiri sesi ini; hasil akan ditandai terganggu.';});
 $('#audio-rate')?.addEventListener('change',e=>audio.playbackRate=Number(e.target.value));
}
async function answer(choice){const s=state.activeSession;if(!s)return;const q=questionById.get(s.questionIds[s.index]);if(s.mode==='practice'&&feedback)return;recordQuestionTime(s);s.answers[q.id]={choice,confidence,elapsed:s.questionTimes[q.id]||0};await save();}

let moving=false;
async function nextQuestion(delta=1){if(moving)return;moving=true;try{await moveQuestion(delta);}finally{moving=false;}}
async function moveQuestion(delta=1){const s=state.activeSession;if(!s)return;const q=questionById.get(s.questionIds[s.index]);if(s.mode!=='practice'&&q.section==='listening'&&!s.played.includes(q.stimulus)&&delta>0){toast('Tunggu rekaman selesai sebelum melanjutkan.');return;}
 const ni=s.index+delta;if(ni<0)return;
 if(ni>=s.questionIds.length){await finish();return;}
 const next=questionById.get(s.questionIds[ni]);if(s.completedSections.includes(next.section)){toast('Bagian sebelumnya sudah terkunci.');return;}
 if(s.mode==='final'&&next.section!==q.section&&delta>0){s.completedSections.push(q.section);s.sectionStartedAt=Date.now();s.deadline=Date.now()+TEST_SECONDS[next.section]*1000;}
 recordQuestionTime(s);s.visited??=[];if(!s.visited.includes(s.questionIds[ni]))s.visited.push(s.questionIds[ni]);s.index=ni;s.lastQuestionAt=Date.now();feedback=false;confidence=s.answers[next.id]?.confidence||'sure';await save();render();}
async function finish(){if(submitting||!state.activeSession)return;submitting=true;try{if(currentAudio)currentAudio.pause();const s=state.activeSession;const id=s.id;state=finalizeSession(state,s,questionById);await save();navigate('result',id);}finally{submitting=false;}}
let expiring=false;
async function expire(){const s=state.activeSession;if(!s||s.mode==='practice'||submitting||expiring)return;const transition=advanceExpiredSections(s,questionById);if(!transition.changed)return;expiring=true;try{if(currentAudio)currentAudio.pause();state.activeSession=transition.session;if(transition.finished){await finish();toast('Waktu habis. Jawaban tersimpan telah dinilai.');}else{feedback=false;await save();render();toast('Waktu bagian sebelumnya habis. Bagian berikutnya dimulai.');}}finally{expiring=false;}}

function result(){const s=state.sessions.find(x=>x.id===detail)||state.sessions.at(-1);if(!s)return empty('Belum ada hasil','Selesaikan latihan atau tes terlebih dahulu.');const qs=s.questionIds.map(id=>questionById.get(id));const r=s.result;const rec=recommendations(state.attempts.filter(a=>a.sessionId===s.id),questions);return `${title(labelMode(s.mode).toUpperCase(),'Satu langkah lebih mengenal diri.',`${date(s.completedAt)} · ${clock(s.elapsed)} durasi sesi`)}${s.invalidAudio?'<p class="notice" role="alert">Sesi terganggu oleh audio/pemulihan. Ini bukan hasil tes lengkap yang sebanding.</p>':''}${s.mode==='diagnostic'?'<p class="notice">Hasil singkat ini hanya pemetaan awal. Jumlah soal tiap topik terbatas; rekomendasi bersifat sementara.</p>':''}<div class="grid four result-stats"><div class="stat"><span>Benar</span><strong>${r.correct}</strong></div><div class="stat"><span>Salah</span><strong>${r.wrong}</strong></div><div class="stat"><span>Kosong</span><strong>${r.blank}</strong></div><div class="stat"><span>Akurasi</span><strong>${percent(r.accuracy)}</strong></div></div><div class="grid three">${cardSection(qs,s.answers)}</div><section class="card"><h2>Rekomendasi materi awal</h2>${rec.length?rec.map(x=>`<div class="focus-row"><h3>${topic(x.skill)}</h3><p>${x.wrong} dari ${x.n} respons tidak tepat.${x.tentative?' Sampel kecil; ini petunjuk awal, bukan simpulan kemampuan.':''}</p>${button('Buka materi →','open-lesson',x.skill,'secondary')}</div>`).join(''):'<p>Belum ada pola kesalahan yang dapat direkomendasikan. Lanjutkan jalur belajar dan gunakan soal baru.</p>'}<p class="caption">Aturan: kelompokkan respons tes terbaru menurut topik, urutkan proporsi kesalahan; di bawah 5 respons diberi label bukti sedikit. Bukan AI atau tes adaptif resmi.</p></section><section><h2>Tinjau jawaban</h2>${qs.map((q,i)=>`<details class="card result-item"><summary>${i+1}. ${sectionName(q.section)} · ${topic(q.skill)} <span>${s.answers[q.id]?.choice===q.answer?'✓ Benar':s.answers[q.id]?'✕ Salah':'— Kosong'}</span></summary><p lang="en">${esc(q.sentence||q.prompt)}</p>${stimulusById.get(q.stimulus)?.type==='reading'?`<details><summary>Bacaan</summary><p class="prose" lang="en">${esc(stimulusById.get(q.stimulus).text)}</p></details>`:''}${explanation(q,s.answers[q.id])}</details>`).join('')}</section>${button('Kembali ke beranda','route','home','secondary')}`;}
function vocabulary(){const due=state.vocabulary.filter(v=>v.due<=Date.now());const card=due[reviewCard%due.length];return `${title('KATA MENJADI BEKAL','Kamus & kosakata','Kamus lokal untuk materi aplikasi. Tidak menyediakan terjemahan bebas kalimat dan tidak tersedia selama tes.')}<section class="card"><form id="dictionary-search" class="search-row"><label for="word-search">Cari kata atau frasa</label><div><input id="word-search" name="word" placeholder="Contoh: evidence, provided that" required maxlength="120">${button('Cari di kamus lokal','search-dictionary')}</div></form><p class="caption">${dictionary.length} entri lokal. Tanda baca di tepi dan kapitalisasi dinormalisasi; beberapa variasi bentuk kata dipetakan secara eksplisit.</p></section><div class="grid two"><section class="card"><span class="badge">FLASHCARD · ${due.length} JATUH TEMPO</span>${card?`<div class="flashcard"><h2 lang="en">${esc(card.word)}</h2>${showMeaning?`<p>${esc(card.meaning)}</p><div class="actions">${button('Belum ingat','review-word','wrong','secondary')}${button('Sudah ingat','review-word','correct')}</div>`:button('Tampilkan makna','reveal-word','','secondary')}</div>`:empty('Belum ada kartu jatuh tempo','Simpan kosakata baru atau kembali saat jadwal ulang tiba.')}<p class="caption">Aturan sederhana: jawaban ingat menjadwalkan 1, 3, 7, lalu 14 hari; belum ingat kembali ke 1 hari. Bukan model ingatan ilmiah yang terkalibrasi.</p></section><section class="card"><h2>Kosakata pribadi</h2>${state.vocabulary.length?state.vocabulary.map(v=>`<div class="word-row"><div><strong lang="en">${esc(v.word)}</strong><p>${esc(v.meaning)}</p><small>Ulang ${date(v.due)} · ${v.reviews} ulasan</small></div>${button('Hapus','remove-word',v.word,'text-button')}</div>`).join(''):'<p class="muted">Belum ada kata tersimpan. Cari kata atau pilih kata pada materi belajar.</p>'}</section></div>`;}
function mistakes(){const failed=state.attempts.filter(a=>a.valid!==false&&a.choice!==questionById.get(a.questionId)?.answer);const ids=[...new Set(failed.map(a=>a.questionId))];return `${title('UBAH KESALAHAN MENJADI PETUNJUK','Catatan kesalahan','Pilih penyebab menurut refleksi Anda. Aplikasi tidak menebak alasan psikologis dari jawaban.')} ${ids.length?ids.map(id=>{const q=questionById.get(id);const a=state.attempts.filter(x=>x.questionId===id);const last=a.at(-1);const n=state.notes.find(x=>x.questionId===id)||{cause:'',text:''};return `<details class="card"><summary>${q.id} · ${topic(q.skill)} <span>${a.length} percobaan</span></summary><p lang="en">${esc(q.sentence||q.prompt)}</p><p>Terakhir: ${last.choice===null?'kosong':esc(q.options[last.choice])} · Kunci: ${esc(q.options[q.answer])}</p><p>${date(last.at)} · ${last.elapsed} detik menjawab · ${a.length-1} pengulangan</p><ul>${a.map(x=>`<li>${date(x.at)} · ${labelMode(x.mode)} · ${x.choice===q.answer?'benar':x.choice===null?'kosong':'salah'} · ${x.elapsed} detik</li>`).join('')}</ul><form class="mistake-note" data-id="${id}"><label>Penyebab menurut saya<select name="cause">${[['','Belum dikategorikan'],['vocabulary','Tidak memahami kosakata'],['structure','Salah memahami struktur'],['evidence','Melewatkan bukti'],['time','Kehabisan waktu'],['guess','Menebak']].map(([k,v])=>`<option value="${k}" ${n.cause===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Catatan pribadi<textarea name="text" maxlength="5000">${esc(n.text)}</textarea></label><button type="submit" class="secondary">Simpan catatan</button></form>${explanation(q,last)}</details>`;}).join(''):empty('Belum ada catatan kesalahan','Setelah latihan atau tes selesai, respons salah dan kosong akan muncul di sini.')}`;}
function progress(){let list=state.attempts.filter(a=>a.valid!==false);const dimensions=[['first','Percobaan pertama',a=>a.first],['repeat','Pengulangan soal',a=>!a.first],['assisted','Belajar dengan bantuan',a=>a.assisted],['test','Tes tanpa bantuan',a=>!a.assisted]];return `${title('PERKEMBANGAN DARI DATA NYATA','Lihat pola, bukan hanya angka.','Akurasi progres adalah benar dibagi respons pada soal yang pernah dibuka, termasuk kosong. Soal yang belum dibuka tetap dihitung kosong pada hasil tes, tetapi tidak dianggap telah dipelajari. Waktu menjawab dicatat sampai berpindah soal, termasuk waktu tab tidak aktif; bukan estimasi kemampuan. Sesi audio terganggu tetap masuk riwayat, tetapi dikeluarkan dari perbandingan dan rekomendasi.')} ${list.length?`<div class="grid four">${dimensions.map(([,label,fn])=>{const x=list.filter(fn);const correct=x.filter(a=>a.choice===questionById.get(a.questionId)?.answer).length;return `<div class="stat"><span>${label}</span><strong>${x.length?percent(correct/x.length):'—'}</strong><small>${x.length} respons</small></div>`;}).join('')}</div><section class="card"><h2>Bagian dan topik</h2><label>Bandingkan kategori<select id="progress-category">${[['all','Semua respons'],...dimensions.map(([k,v])=>[k,v])].map(([k,v])=>`<option value="${k}" ${detail===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="table-wrap"><table><thead><tr><th>Bagian / topik</th><th>Respons</th><th>Benar</th><th>Akurasi</th><th>Rata-rata waktu</th></tr></thead><tbody>${[...Object.entries(SECTIONS),...Object.entries(skills).map(([k,v])=>[k,v[1]])].map(([key,label])=>{const fn=dimensions.find(([k])=>k===detail)?.[2]||(()=>true);const x=list.filter(a=>fn(a)&&[questionById.get(a.questionId)?.section,questionById.get(a.questionId)?.skill].includes(key));const correct=x.filter(a=>a.choice===questionById.get(a.questionId)?.answer).length;return `<tr><th>${label}</th><td>${x.length}</td><td>${correct}</td><td>${x.length?percent(correct/x.length):'—'}</td><td>${x.length?Math.round(x.reduce((n,a)=>n+a.elapsed,0)/x.length)+' dtk':'—'}</td></tr>`;}).join('')}</tbody></table></div></section><section class="card"><h2>Riwayat sesi</h2>${state.sessions.slice().reverse().map(s=>`<button class="history-row" data-action="result" data-value="${s.id}"><span>${labelMode(s.mode)} ${s.invalidAudio?'· terganggu':''}<small>${date(s.completedAt)} · ${clock(s.elapsed)}</small></span><strong>${s.result.correct}/${s.result.total} →</strong></button>`).join('')}</section>`:empty('Riwayat masih kosong','Mulai diagnostik atau latihan. Tidak ada grafik atau aktivitas contoh yang ditambahkan.')}`;}
function settings(){return `${title('PERANGKAT & DATA','Pengaturan ruang pribadi','Tanpa akun dan tanpa server. Progres tidak otomatis berpindah ke perangkat lain.')}<section class="card prose"><h2>Cadangan progres</h2><p>Ekspor berkala agar progres tidak hilang saat data browser dihapus. Impor mengganti seluruh profil setelah struktur, versi, dan rujukan soal divalidasi. Progres pribadi tidak dikirim ke GitHub.</p><div class="actions">${button('Ekspor JSON','export')}<label class="file-button secondary">Impor JSON<input id="import-file" type="file" accept=".json,application/json"></label></div><p>Skema penyimpanan versi 2. Cadangan versi 1 dimigrasikan dengan nilai awal untuk bidang baru. Versi lain ditolak.</p><h2>Tampilan</h2>${button(state.preferences.theme==='light'?'Gunakan tema gelap':'Gunakan tema terang','theme','','secondary')}<h2>Inventaris terpasang</h2><ul>${Object.entries(SECTIONS).map(([s,name])=>`<li>${name}: ${questions.filter(q=>q.section===s).length} soal.</li>`).join('')}<li>${stimuli.filter(s=>s.type==='reading').length} bacaan dan ${stimuli.filter(s=>s.type==='listening'&&s.audioStatus==='ready').length} rekaman soal siap.</li></ul><p>Tidak ada soal resmi ETS yang direproduksi. Kesulitan dan kunci masih memerlukan peninjauan ahli independen. Rincian asal dan batasan ada di dokumen repository.</p><h2>Sumber resmi</h2><ul><li><a href="https://www.ets.org/toefl/itp/test-content.html" target="_blank" rel="noopener">Format TOEFL ITP di ETS ↗</a></li><li><a href="https://www.ets.org/toefl/itp/prepare.html" target="_blank" rel="noopener">Persiapan resmi ETS ↗</a></li><li><a href="https://www.ets.org/legal/permissions/how-to-request.html" target="_blank" rel="noopener">Permohonan izin reproduksi ETS ↗</a></li></ul><p class="notice">Akses sumber ETS dari lingkungan pengembangan ditolak jaringan. Rujukan ini tidak boleh dianggap sudah diverifikasi ulang langsung. Latihan internal tetap orisinal.</p></section>`;}
async function dictionaryPanel(word){if(state.activeSession&&state.activeSession.mode!=='practice'){toast('Kamus tidak tersedia selama tes.');return;}word=normalizeWord(word).slice(0,120);if(!word)return;const entry=dictionary.find(e=>e.word===(wordAliases[word]||word));const saved=state.vocabulary.find(v=>v.word===word);
 $('#dictionary').innerHTML=`<div class="section-heading"><span class="eyebrow">KAMUS LOKAL</span>${button('Tutup ×','close-dictionary','','text-button')}</div><h2 id="dict-title" lang="en">${esc(entry?.word||word)}</h2>${entry?`<span class="badge">${entry.pos}</span><p class="dict-meaning">${entry.meaning}</p><blockquote lang="en">${entry.example}</blockquote><p>${entry.note}</p><p class="caption">Makna dipilih sesuai konteks entri; periksa kembali kalimat yang sedang Anda baca.</p>${button('Simpan ke kosakata','save-word',entry.word)}`:`<p>Kata ini belum tersedia di kamus lokal. Aplikasi tidak akan mengarang artinya.</p><form id="custom-word" data-word="${esc(word)}"><label>Catatan makna pribadi<textarea name="meaning" required maxlength="1000">${esc(saved?.meaning||'')}</textarea></label><button type="submit" class="primary">Simpan catatan pribadi</button></form><p><a href="https://dictionary.cambridge.org/dictionary/english/${encodeURIComponent(word)}" target="_blank" rel="noopener">Cari di Cambridge Dictionary ↗</a></p><p class="caption">Tautan eksternal memerlukan internet; isi dan aksesnya dikelola penyedia tersebut.</p>`}`;
 $('#dictionary').showModal();$('#dictionary [data-action="close-dictionary"]')?.addEventListener('click',()=>$('#dictionary').close());$('#dictionary [data-action="save-word"]')?.addEventListener('click',()=>saveWord(entry.word,entry.meaning));$('#custom-word')?.addEventListener('submit',async e=>{e.preventDefault();await saveWord(word,new FormData(e.target).get('meaning').trim());});}
async function saveWord(word,meaning){if(!meaning)return;if(!state.vocabulary.some(v=>v.word===word)){state.vocabulary.push({word,meaning,stage:-1,due:Date.now(),reviews:0});}else{state.vocabulary=state.vocabulary.map(v=>v.word===word?{...v,meaning}:v);}await save();toast('Kosakata tersimpan.');$('#dictionary').close();if(route==='vocabulary')render();}
function attach(){
 document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();testPlan=null;navigate(el.dataset.route);}));
 document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',e=>{if(el.closest('form')&&['search-dictionary'].includes(el.dataset.action))return;e.preventDefault();act(el.dataset.action,el.dataset.value).catch(err=>toast(err.message));}));
 $('#filters')?.addEventListener('change',e=>{const values=Object.fromEntries(new FormData(e.currentTarget));if(e.target.name==='section')values.skill='all';filter=values;render();});
 document.querySelectorAll('input[name="answer"]').forEach(el=>el.addEventListener('change',()=>answer(Number(el.value)).catch(()=>{})));
 document.querySelectorAll('input[name="confidence"]').forEach(el=>el.addEventListener('change',async()=>{confidence=el.value;const s=state.activeSession,q=questionById.get(s.questionIds[s.index]);if(s.answers[q.id]){s.answers[q.id].confidence=confidence;await save();}}));
 $('#audio-confirm')?.addEventListener('change',e=>audioChecked=e.target.checked);
 $('#dictionary-search')?.addEventListener('submit',e=>{e.preventDefault();dictionaryPanel(new FormData(e.target).get('word'));});
 document.querySelectorAll('[data-content]').forEach(el=>el.addEventListener('mouseup',()=>{const selection=window.getSelection();const word=selection?.toString().trim();if(word&&word.length<60&&word.split(/\s+/).length<=3&&el.contains(selection.anchorNode))dictionaryPanel(word);}));
 $('#progress-category')?.addEventListener('change',e=>{detail=e.target.value;render();});
 document.querySelectorAll('.mistake-note').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));state.notes=state.notes.filter(n=>n.questionId!==form.dataset.id);state.notes.push({questionId:form.dataset.id,...data});await save();toast('Catatan tersimpan.');}));
 $('#import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10_000_000)throw Error('Berkas melebihi 10 MB.');const parsed=validateBackup(JSON.parse(await file.text()),new Set(questions.map(q=>q.id)),new Set(lessons.map(l=>l.id)));if(!confirm('Ganti seluruh progres perangkat ini dengan cadangan tervalidasi? Ekspor dahulu jika perlu.'))return;state=parsed;await save();toast('Cadangan berhasil dipulihkan.');navigate(state.activeSession?'session':'settings');}catch(err){toast(err.message);e.target.value='';}});
}
async function act(action,value){switch(action){
 case 'route':navigate(value);break;
 case 'theme':state.preferences.theme=state.preferences.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.preferences.theme;const toggle=document.querySelector('[data-action=theme]');if(toggle){toggle.setAttribute('aria-label',state.preferences.theme==='light'?'Aktifkan tema gelap':'Aktifkan tema terang');toggle.textContent=state.preferences.theme==='light'?'☾':'☀';}await save();if(route!=='session')render();break;
 case 'open-lesson':navigate('lesson',value);break;
 case 'complete-lesson':if(!state.completedLessons.includes(value))state.completedLessons.push(value);await save();render();toast('Materi ditandai selesai.');break;
 case 'lesson-practice':case 'reinforce':{let pool=questions.filter(q=>q.split==='practice'&&q.skill===value);if(!pool.length)pool=questions.filter(q=>q.split==='practice'&&q.section===skills[value]?.[0]);const groups=groupQuestions(pool);const group=action==='reinforce'?(groups.find(g=>g.every(q=>!state.attempts.some(a=>a.questionId===q.id)))||groups.at(-1)):groups[0];if(!group){toast('Belum ada latihan khusus topik ini. Coba bagian yang sama di bank latihan.');navigate('bank');break;}await startSession('practice',group);break;}
 case 'practice-group':{const q=questionById.get(value);await startSession('practice',questions.filter(x=>x.split==='practice'&&(q.stimulus?x.stimulus===q.stimulus:x.id===q.id)));break;}
 case 'plan':plan(value);break;
 case 'cancel-plan':testPlan=null;render();break;
 case 'start-test':{if(!testPlan)return;if(testPlan.qs.some(q=>q.section==='listening')&&!audioChecked){toast('Periksa audio dan centang konfirmasi terlebih dahulu.');return;}if(testPlan.qs.some(q=>q.section==='listening'&&stimulusById.get(q.stimulus)?.audioStatus!=='ready')){toast('Rekaman belum siap.');return;}if(testPlan.mode==='final'&&testPlan.qs.length!==140){toast('Paket final belum lengkap 140 soal.');return;}await startSession(testPlan.mode,testPlan.qs);break;}
 case 'resume':navigate('session');break;
 case 'bookmark':state.bookmarks=state.bookmarks.includes(value)?state.bookmarks.filter(id=>id!==value):[...state.bookmarks,value];await save();render();break;
 case 'clear-answer':delete state.activeSession.answers[state.activeSession.questionIds[state.activeSession.index]];await save();render();break;
 case 'check-answer':{const s=state.activeSession;const q=questionById.get(s.questionIds[s.index]);if(!s.answers[q.id]){toast('Pilih jawaban sebelum membuka pembahasan.');return;}feedback=true;render();break;}
 case 'next':await nextQuestion();break;
 case 'previous':await nextQuestion(-1);break;
 case 'finish-prompt':if(confirm('Akhiri sesi dan nilai jawaban yang tersimpan? Soal tanpa jawaban akan dihitung kosong.'))await finish();break;
 case 'play-audio':{const s=state.activeSession,q=questionById.get(s.questionIds[s.index]);if(s.played.includes(q.stimulus))return;const b=$('[data-action="play-audio"]');b.disabled=true;try{s.playingStimulus=q.stimulus;await save();await currentAudio.play();$('#audio-status').textContent='Audio sedang diputar. Dengarkan sampai selesai.';}catch(err){s.invalidAudio=true;await save();b.disabled=false;toast('Audio tidak dapat dimulai: '+err.message);}break;}
 case 'result':navigate('result',value);break;
 case 'export':{await saveQueue;const blob=new Blob([backup(state)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ruang-toefl-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
 case 'lookup-selection':{const word=prompt('Kata atau frasa yang ingin dicari:');if(word)await dictionaryPanel(word);break;}
 case 'search-dictionary':break;
 case 'reveal-word':showMeaning=true;render();break;
 case 'review-word':{const due=state.vocabulary.filter(v=>v.due<=Date.now());const v=due[reviewCard%due.length];if(!v)return;state.vocabulary=state.vocabulary.map(x=>x.word===v.word?reviewSchedule(x,value==='correct'):x);showMeaning=false;await save();render();break;}
 case 'remove-word':if(confirm('Hapus kata ini dari kosakata pribadi?')){state.vocabulary=state.vocabulary.filter(v=>v.word!==value);await save();render();}break;
 }}
async function boot(){try{state=await readState();if(state.activeSession?.playingStimulus){state.activeSession.invalidAudio=true;delete state.activeSession.playingStimulus;await save();}route=state.activeSession?'session':'home';render();timer=setInterval(()=>{const s=state.activeSession;if(s&&s.mode!=='practice'){const el=$('#timer-value');if(el)el.textContent=clock(remaining(s.deadline));expire().catch(e=>toast(e.message));}},500);}catch(e){$('#app').innerHTML=`<main class="fatal"><h1>Progres belum dapat dibuka</h1><p>${esc(e.message)}</p><p>Pastikan IndexedDB diizinkan. Data lama tidak dihapus. Tutup tab lain dan muat ulang halaman.</p><button id="reload" class="primary">Coba lagi</button></main>`;$('#reload').onclick=()=>location.reload();}}
// One writer per origin prevents two tabs from overwriting local progress.
if(navigator.locks)navigator.locks.request('ruang-toefl-writer',{ifAvailable:true},async lock=>{if(!lock){$('#app').innerHTML='<main class="fatal"><h1>Aplikasi terbuka di tab lain</h1><p>Gunakan satu tab agar jawaban tidak saling menimpa.</p><button class="primary" onclick="location.reload()">Coba lagi</button></main>';return;}await boot();await new Promise(()=>{});});else boot();
